  { node_id: 'launch_adapter', label: 'Launch adapter worker', kind: 'worker', depends_on: [] },
  { node_id: 'handoff', label: 'Freeze', kind: 'prepare', depends_on: ['launch_ui', 'launch_adapter'] },
