function worker(task: string, checkId = 'frontend-build') {
  return { role: 'frontend', task, prompt: null, owned_paths: ['src'], checks: [{ id: checkId, kind: 'build', argv: ['npm', 'run', 'build'], command: 'npm run build', timeout_seconds: 60, scenarios: [] }],
    launch: null, completion: null, handoff: null, stop: null }
}
function inputs(uiTask: string, checkId?: string) {
  return { feature: 'f', policy_version: '1.1.0', base_commit: BASE, source_branch: 'feature/x', mode: 'manual', automatic: null, setup: [], max_verification_attempts: 3, failure_drill: null,
    workers: { ui: worker(uiTask, checkId) } }
}
function review(requirement: string) {
  return { attempt: 1, transport: 'native', reviewer_session_id: 'r', independent: true, bundle_sha256: 'f'.repeat(64), candidate_commit: OUT, verdict: 'approved',
    findings: [{ severity: 'P2', message: 'm', disposition: 'open', worker: 'ui', requirement }], reviewed_at: T0, diff: null }
}
async function writeRun(root: string, runId: string, extra: Record<string, unknown>) {
  const dir = join(root, runId)
  await mkdir(dir, { recursive: true })
  await writeFile(join(dir, 'plan.json'), JSON.stringify({ run_id: runId, base_commit: BASE }))
  await writeFile(join(dir, 'run-state.json'), JSON.stringify({ version: '1.2.0', run_id: runId, base_commit: BASE, created_at: T0, updated_at: T0, definition: { name: 'g', nodes: NODES },
    values: { review: { verdict: 'approved' } }, next: [], tasks: [], events: [], verification_packets: [], ...extra }))
}

const root = await mkdtemp(join(tmpdir(), 'probe-'))
const runs = join(root, 'runs')
await mkdir(runs, { recursive: true })
const config = await parseProjectsConfig(JSON.stringify({ version: 1, projects: [{ project_id: 'p', name: 'P', repository: join(root, 'repo'), workflows: [{ workflow_id: 'w', runs_root: runs, definition: { name: 'g', nodes: NODES } }] }] }), 'probe')
const app = createApp([], { projects: config, logger: false } as any)
