  await writeRun(runs, 'long', { inputs: inputs(task), review: review(quote) })
  const rv = await get('/api/projects/p/workflows/w/runs/long/reviews/1')
  const inp = await get('/api/projects/p/workflows/w/runs/long/inputs')
  console.log('B review status', rv.status, 'found_in', JSON.stringify(rv.json().findings[0].requirement_found_in))
  console.log('B inputs status', inp.status, 'task.text includes quote?', inp.json().workers[0].task.text.includes(quote), 'truncated', inp.json().workers[0].task.truncated)
  await rm(join(runs, 'long'), { recursive: true })

  // (c) path spellings in served task text
  const leaky = `Read [${root}/x/y](${root}/x/y) and |${root}/x/y| and file://${root}/x/y and <${root}/x/y> and *${root}/x/y* first.`
  await writeRun(runs, 'leak', { inputs: inputs(leaky) })
  const li = await get('/api/projects/p/workflows/w/runs/leak/inputs')
  console.log('C inputs status', li.status, 'contains root?', li.body.includes(root))
  console.log('C served task:', JSON.stringify(li.json().workers[0].task.text))
  await rm(join(runs, 'leak'), { recursive: true })

  // (a) a check id that the policy schema allows but the projects contract does not
  await writeRun(runs, 'ok-run', { inputs: null, review: null })
  await writeRun(runs, 'odd-id', { inputs: inputs('task', 'unit tests') })
  const list = await get('/api/projects/p/workflows/w/runs')
  console.log('A list status', list.status, list.body.slice(0, 220))
  const okRun = await get('/api/projects/p/workflows/w/runs/ok-run')
  console.log('A sibling detail status', okRun.status)
} finally {
  await app.close()
  await rm(root, { recursive: true, force: true })
}
EOF
